const cfg = $('Load Config').first().json;
const card = $('Get Card').first().json;
const settings = $('Get Vision Model').first().json || {};
const rows = $('Get Templates').all().map((i) => i.json);
const tpl = rows.find((r) => r.slug === 'analysis_prompt');
if (!tpl || !tpl.body) throw new Error('no active analysis_prompt template in prompt_templates');
const urls = $input.all().map((i) => cfg.sbUrl + '/storage/v1' + String(i.json.signedURL || '')).filter((u) => /token=/.test(u));
if (!urls.length) throw new Error('no signed reference URLs');
const lines = (Array.isArray(card.print_text) ? card.print_text : []).map((t) => (t && t.text) || '').filter(Boolean);
const client = card.clients || {};
const sb = (client.style_brief && typeof client.style_brief === 'object') ? client.style_brief : {};
// one SLOT_BLOCK per attached image: cards.reference_roles (stamped at submit / New card), else the settings order, else the recorded default
const BLOCK = { subject: 'IMAGE n - WHAT TO MAKE: the hero subject and exactly how it is posed and framed, every supporting element and its placement, the overall layout and where the text zones sit. Do NOT describe its colours, technique or lettering.', art_style: 'IMAGE n - ART STYLE: only how it is drawn - medium, line weight and style, shading method, texture and distress, edge finish, rendering realism, and the palette as uppercase hex with a role per colour. Do NOT describe its subject or its words.', typography: 'IMAGE n - LETTERING: only the letterforms - headline lettering family and weight, secondary lettering, placement relative to the art, case, effects (outline, inline hatching, arch, banner, drop line, distressed). Do NOT describe its subject or colours.' };
const order = Array.isArray(settings.reference_roles) && settings.reference_roles.length ? settings.reference_roles : ['subject', 'art_style', 'typography'];
const given = Array.isArray(card.reference_roles) && card.reference_roles.length ? card.reference_roles : order;
const roles = urls.map((u, i) => (BLOCK[given[i]] ? given[i] : (BLOCK[order[i]] ? order[i] : 'subject')));
const vars = { NICHE: String(sb.niche || '').trim() || client.name || '', CLIENT_NAME: client.name || '', CLIENT_NOTES: client.notes || '', GARMENT_COLORS: JSON.stringify(client.garment_colors || []), BRIEF: card.brief_text || 'not given', TEXT_LINES: lines.length ? lines.join('\n') : 'NONE', IMAGE_COUNT: String(urls.length), SLOT_BLOCKS: roles.map((r, i) => BLOCK[r].replace('IMAGE n', 'IMAGE ' + (i + 1))).join('\n') };
const text = String(tpl.body).replace(/\{\{\s*([A-Z_]+)\s*\}\}/g, (m, k) => (k in vars ? vars[k] : m));
const content = [{ type: 'text', text }].concat(urls.map((url) => ({ type: 'image_url', image_url: { url } })));
return { json: { body: { messages: [{ role: 'user', content }], response_format: { type: 'json_object' } }, template_version: tpl.version, reference_urls: urls, text_lines: lines, roles } };

if (!$json.choices) { const e = (typeof $json.error === 'object' && $json.error) || {}; const via = $('OpenRouter Analyze').isExecuted ? ($('Analyze References').isExecuted ? 'Kie and OpenRouter' : 'OpenRouter') : 'Kie'; let why = String($json.msg || e.message || (typeof $json.error === 'string' ? $json.error : '') || 'no reply'); const inner = why.match(/message\\?":\\?"([^"\\]+)/); if (inner) why = inner[1]; const code = $json.code || e.status || e.httpCode || e.code || '?'; if (via !== 'Kie' && (String(code) === '401' || String(code) === '403')) why = 'OpenRouter API key missing or invalid - add it in n8n WF-0 Studio Config (OpenRouter Config node)'; throw new Error('Vision service unavailable (' + via + ' error ' + code + ' - ' + why.replace(/:/g, ' -').slice(0, 160) + '). Nothing was changed; try again in a few minutes.'); }
const content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
const cleaned = String(content).replace(/```json|```/g, '').trim();
const tryParse = (t) => { try { return JSON.parse(t); } catch (e) { return null; } };
let analysis = tryParse(cleaned); if (analysis === null) { const m = cleaned.match(/\{[\s\S]*\}/); analysis = m ? tryParse(m[0]) : null; }
const req = $('Build Analysis Request').first().json; const roles = Array.isArray(req.roles) ? req.roles : [];
const str = (v) => (v === undefined || v === null || typeof v === 'object' ? '' : String(v).trim()); const arr = (v) => (Array.isArray(v) ? v.map(str).filter(Boolean) : []); const join = (parts, sep) => parts.filter(Boolean).join(sep); const w = (v, suf, pre) => (str(v) ? (pre || '') + str(v) + (suf || '') : '');
if (analysis && Array.isArray(analysis.references)) { // analysis_prompt v3 - one object per attached image, each read for ONE role; the flat keys are the day-one compat view, each mapped from its own slot
  const refs = analysis.references.filter((r) => r && typeof r === 'object' && !Array.isArray(r)).map((r, i) => Object.assign({ slot: i + 1 }, r, { role: str(r.role) || roles[(Number(r.slot) || i + 1) - 1] || '' }));
  const by = (role) => refs.find((r) => r.role === role) || {}; const s = by('subject'), a = by('art_style'), t = by('typography'); const h = (s.hero && typeof s.hero === 'object') ? s.hero : { subject: s.hero }; const th = t.headline || {}, ts = t.secondary || {}; const sup = arr(s.supporting_elements);
  const art_style = join([w(a.medium), w(a.realism, ' realism'), w(join([str(a.line_weight), str(a.line_style)], ' '), ' linework'), w(a.shading, ' shading'), w(a.texture, ' texture'), w(a.edge_finish, ' edges')], '; '); const composition = join([w(s.layout, ' layout'), w(h.framing, ' framing'), w(s.text_zones, '', 'text zones ')], '; ');
  const subject_structure = join([join([str(h.subject), str(h.pose), w(h.framing, ' framing'), w(h.scale, ' scale')], ', '), sup.length ? 'supporting elements ' + sup.join(', ') : ''], '; '); const typography_transcription = join([w(join([str(th.family), str(th.weight), arr(th.effects).join(', ')], ' '), '', 'headline '), w(join([str(ts.family), str(ts.weight), arr(ts.effects).join(', ')], ' '), '', 'secondary '), w(t.placement, '', 'placed '), w(t.case, ' case')], '; ');
  analysis = { art_style, palette: Array.isArray(a.palette) ? a.palette : '', subject_structure, composition, typography_transcription, text_detected: [...new Set(refs.flatMap((r) => arr(r.text_detected)))], notes: str(analysis.notes), references: refs, roles, same_design: analysis.same_design === true, template_version: req.template_version || 3 };
} else if (Array.isArray(analysis)) { const objs = analysis.filter((o) => o && typeof o === 'object' && !Array.isArray(o)); const primary = objs[0] || null; if (primary && objs.length > 1) primary.notes = [str(primary.notes), 'Supporting references (style and subject cues only, not the design to re-create) - ' + objs.slice(1).map((o, i) => 'IMAGE ' + (i + 2) + ' - ' + str(o.subject_structure || o.art_style).slice(0, 300)).join(' | ')].filter(Boolean).join(' '); analysis = primary; } // legacy v2 array reply - IMAGE 1 is the design, the rest become a note
if (!analysis || typeof analysis !== 'object' || Array.isArray(analysis)) { // v1 text reply (STYLE: / TYPOGRAPHY_TEXT: / TYPOGRAPHY_STYLE:) -> minimal reference_analysis object
  const block = (k) => { const r = cleaned.match(new RegExp('(?:^|\\n)' + k + ':\\s*([\\s\\S]*?)(?=\\n[A-Z_]+:|$)')); return r ? r[1].trim() : ''; }; const style = block('STYLE'), text = block('TYPOGRAPHY_TEXT'), hasText = Boolean(text) && !/^none$/i.test(text);
  if (!style) throw new Error('reference analysis is neither JSON nor a STYLE block - reply was ' + cleaned.slice(0, 200).replace(/:/g, '='));
  analysis = { art_style: style, palette: '', subject_structure: '', typography_transcription: hasText ? text : '', text_detected: hasText ? [text] : [], composition: '', notes: 'parsed from a STYLE/TYPOGRAPHY_TEXT text reply (analysis_prompt v1 format)' }; }
if (!Array.isArray(analysis.text_detected)) analysis.text_detected = analysis.typography_transcription && !/^none$/i.test(String(analysis.typography_transcription)) ? [String(analysis.typography_transcription)] : [];
return { json: { reference_analysis: analysis, template_version: req.template_version, reference_count: req.reference_urls.length } };
